/* 运行监测：一个测点、一个时间范围，图表与原始读数互切。 */
window.EamArchiveTrendView=(()=>{
 const states=new WeakMap(),r=EamArchiveTrendRules;
 const el=(tag,text,cls='')=>{const n=document.createElement(tag);n.textContent=text;n.className=cls;return n;};
 const number=value=>Number(value).toLocaleString('zh-CN',{maximumFractionDigits:3});
 const inputTime=t=>Number.isFinite(t)?new Date(t+8*3600000).toISOString().slice(0,16):'';
 function state(host,mode,message,retry){const previous=states.get(host);if(previous){previous.redraw=null;}host.replaceChildren(el('p',message||(mode==='loading'?'正在读取测点配置与采样…':'监测读取失败'),'alert '+(mode==='loading'?'alert-secondary':'alert-danger')));if(mode!=='loading'&&retry){const b=el('button','重新读取','btn btn-sm btn-outline-primary');b.type='button';b.onclick=retry;host.append(b);}}
 function chart(host,result,config,openRecord){
  if(!result.valid.length){host.append(el('p','当前范围没有质量合格且时间有效的数值；可切换原始数据核对。','alert alert-secondary'));return;}
  const values=result.valid.map(row=>row[config.metric]),bounds=values.concat([config.lower,config.upper].filter(Number.isFinite)),minimum=Math.min(...bounds),maximum=Math.max(...bounds),padding=Math.max((maximum-minimum)*.12,Math.abs(maximum)*.01,.1),low=minimum-padding,high=maximum+padding;
  if(!Number.isFinite(high-low)){host.append(el('p','数值跨度超出图表范围，请查看原始数据。','alert alert-warning'));return;}
  const width=Math.max(280,Math.round(host.clientWidth)||720),right=width-25;
  
  const times=result.raw.map(row=>r.time(row.eventAt)).filter(Number.isFinite),start=Math.min(...times),end=Math.max(...times),x=t=>end===start?(70+right)/2:70+(t-start)/(end-start)*(right-70),y=value=>250-(value-low)/(high-low)*200;
  const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 '+width+' 310');svg.setAttribute('role','group');svg.setAttribute('aria-label',config.name+'趋势，单位'+config.unit+'，有效读数'+result.valid.length+'条');svg.classList.add('archive-trend-chart');
  const shape=(tag,attrs)=>{const n=document.createElementNS(svg.namespaceURI,tag);for(const [key,value]of Object.entries(attrs))n.setAttribute(key,value);svg.append(n);return n;};
  for(let i=0;i<=4;i++){const value=low+(high-low)*i/4,py=y(value);shape('line',{x1:70,x2:right,y1:py,y2:py,stroke:'var(--bs-border-color)'});shape('text',{x:60,y:py+4,'text-anchor':'end','font-size':12,fill:'currentColor'}).textContent=number(value);}
  shape('text',{x:70,y:22,'font-size':13,fill:'currentColor'}).textContent=config.name+' / '+config.unit;
  for(const [key,label]of [['upper','上限'],['lower','下限']])if(Number.isFinite(config[key])){shape('line',{x1:70,x2:right,y1:y(config[key]),y2:y(config[key]),stroke:'var(--bs-warning)','stroke-dasharray':'6 4'});shape('text',{x:right,y:y(config[key])-5,'text-anchor':'end','font-size':12,fill:'currentColor'}).textContent=label+' '+config[key]+' '+config.unit;}
  for(const segment of result.segments)if(segment.length>1)shape('polyline',{points:segment.map(row=>x(r.time(row.eventAt))+','+y(row[config.metric])).join(' '),fill:'none',stroke:'var(--bs-primary)','stroke-width':2.5});
  const reading=el('p','悬停或用键盘选中采样点查看读值；点击查看原始记录。','small mt-2 mb-0');reading.setAttribute('role','status');reading.dataset.trendReading='';
  for(const row of result.valid){const label=row.eventAt+' · '+number(row[config.metric])+' '+config.unit+' · '+r.quality(row.quality),dot=shape('circle',{cx:x(r.time(row.eventAt)),cy:y(row[config.metric]),r:5,fill:result.exceeded.includes(row)?'var(--bs-danger)':'var(--bs-primary)'});const hit=shape('circle',{cx:x(r.time(row.eventAt)),cy:y(row[config.metric]),r:25,fill:'transparent',tabindex:0,role:'button','aria-label':label});const title=document.createElementNS(svg.namespaceURI,'title');title.textContent=label;hit.append(title);hit.onmouseenter=hit.onfocus=()=>{reading.textContent=label;};hit.onclick=()=>openRecord(row,'trend');hit.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();openRecord(row,'trend');}};}
  shape('text',{x:70,y:282,'font-size':12,fill:'currentColor'}).textContent=EamProduct.time(new Date(start).toISOString());if(end!==start)shape('text',{x:right,y:302,'font-size':12,'text-anchor':'end',fill:'currentColor'}).textContent=EamProduct.time(new Date(end).toISOString());host.append(svg,reading);
 }
 function render(host,rows,display,options){
  const points=display.trendPoints||[display.trend].filter(Boolean),s=states.get(host)||{view:'chart',range:'all',point:'',from:'',to:'',page:1,quality:''};states.set(host,s);host.replaceChildren();
  if(!points.length){host.append(el('p','当前设备尚未配置测点、单位和采样来源。','alert alert-secondary'));return;}
  const config=points.find(p=>p.pointId===s.point)||points[0];s.point=config.pointId;const signal=display.trendState||{status:'demo',asOf:display.asOf};
  if(!s.from){const first=rows.map(row=>r.time(row.eventAt)).filter(Number.isFinite);s.from=inputTime(first.length?Math.min(...first):r.time(signal.asOf)-86400000);s.to=inputTime(r.time(signal.asOf));}
  const rerender=()=>render(host,rows,display,options);s.redraw=rerender;s.width=Math.round(host.clientWidth);if(!s.observer&&typeof ResizeObserver!=='undefined'){s.observer=new ResizeObserver(()=>{const width=Math.round(host.clientWidth);if(width&&width!==s.width&&s.redraw)s.redraw();});s.observer.observe(host);}const controls=el('div','','d-flex flex-wrap gap-2 align-items-end mb-3');
  const select=(label,choices,value,change)=>{const wrap=el('label',label,'small d-flex flex-column gap-1'),input=document.createElement('select');input.className='form-select form-select-sm';input.setAttribute('aria-label',label);for(const [id,name]of choices)input.append(new Option(name,id));input.value=value;input.onchange=()=>{change(input.value);s.page=1;rerender();};wrap.append(input);controls.append(wrap);return input;};
  select('测点选择',points.map(p=>[p.pointId,p.name+' / '+p.unit]),s.point,value=>{s.point=value;});select('时间范围',[['all','全部采样'],['day','快照前24小时'],['week','快照前7天'],['custom','自定义区间']],s.range,value=>{s.range=value;});
  if(s.range==='custom'){for(const [key,label]of [['from','起始时间'],['to','结束时间']]){const wrap=el('label',label,'small d-flex flex-column gap-1'),input=document.createElement('input');input.type='datetime-local';input.dataset.trendBound=key;input.className='form-control form-control-sm';input.setAttribute('aria-label',label);input.value=s[key];input.oninput=()=>{s[key]=input.value;};wrap.append(input);controls.append(wrap);}const apply=el('button','应用区间','btn btn-sm btn-primary');apply.type='button';apply.dataset.trendApply='';apply.onclick=()=>{for(const input of controls.querySelectorAll('[data-trend-bound]'))s[input.dataset.trendBound]=input.value;s.page=1;rerender();};controls.append(apply);}
  const refresh=el('button','刷新监测','btn btn-sm btn-outline-secondary');refresh.type='button';refresh.onclick=options.onRefresh;controls.append(refresh);host.append(controls);
  const nav=el('div','','nav nav-pills gap-2 mb-3');for(const [key,label]of [['chart','趋势图'],['raw','原始数据']]){const b=el('button',label,'nav-link'+(s.view===key?' active':''));b.type='button';b.dataset.trendView=key;b.setAttribute('aria-pressed',String(s.view===key));b.onclick=()=>{s.view=key;rerender();};nav.append(b);}host.append(nav);
  host.append(el('p',signal.status==='stale'?'信号失效：当前运行状态未知，历史曲线不能证明设备正在正常运行。':'静态示例采样，不代表实时信号；相对时间范围按来源快照计算。','alert '+(signal.status==='stale'?'alert-warning':'alert-secondary')+' py-2 small'));
  host.append(el('p','测点 '+config.pointId+' · 单位 '+config.unit+' · 来源快照 '+(signal.asOf||'未提供')+' · 阈值依据 '+(config.thresholdSource||'未配置阈值'),'small text-secondary'));
  let result;try{result=r.select(rows,config,{...s,asOf:signal.asOf});}catch(error){host.append(el('p',error.message,'alert alert-danger'));return;}
  host.append(el('p','当前范围 '+result.raw.length+' 条 · 有效 '+result.valid.length+' 条 · 无效或待核验 '+(result.raw.length-result.valid.length)+' 条 · 越限 '+result.exceeded.length+' 条','small fw-semibold'));
  const open=row=>options.openRecord({...row,detailSections:[{title:'采样信息',fields:[['测点',config.name+' / '+config.pointId],['采样时间',row.eventAt],['读数',typeof row[config.metric]==='number'&&Number.isFinite(row[config.metric])?number(row[config.metric])+' '+config.unit:'无有效数值'],['质量',r.quality(row.quality)],['判定',result.valid.includes(row)?result.exceeded.includes(row)?'越限':'有效采样':'不参与曲线'],['阈值依据',config.thresholdSource||'未配置阈值'],['来源',row.source]]}]},'trend');
  if(s.view==='chart'){chart(host,result,config,open);return;}
  const tableFilters=el('div','','d-flex gap-2 mb-2');const quality=document.createElement('select');quality.className='form-select form-select-sm';quality.setAttribute('aria-label','原始数据质量筛选');for(const [value,title]of [['','全部质量'],['valid','仅合格有效'],['invalid','无效或待核验']])quality.append(new Option(title,value));quality.value=s.quality;quality.onchange=()=>{s.quality=quality.value;s.page=1;rerender();};tableFilters.append(quality);host.append(tableFilters);
  const raw=result.raw.filter(row=>!s.quality||(s.quality==='valid'?result.valid.includes(row):!result.valid.includes(row))),pages=Math.max(1,Math.ceil(raw.length/8));s.page=Math.min(s.page,pages);
  const region=el('div','','table-wrapper'),table=el('table','','data-table'),head=el('thead',''),tr=el('tr','');for(const title of ['采样时间','读数 / '+config.unit,'数据质量','判定','操作'])tr.append(el('th',title));head.append(tr);table.append(head);const body=el('tbody','');
  for(const row of raw.slice((s.page-1)*8,s.page*8)){const tr=el('tr','');for(const value of [row.eventAt||'未记录',typeof row[config.metric]==='number'&&Number.isFinite(row[config.metric])?number(row[config.metric]):'无有效数值',r.quality(row.quality),result.valid.includes(row)?result.exceeded.includes(row)?'越限':'有效采样':'不参与曲线'])tr.append(el('td',value));const td=el('td',''),button=el('button','详情','btn btn-sm btn-outline-secondary');button.type='button';button.onclick=()=>open(row);td.append(button);tr.append(td);body.append(tr);}table.append(body);region.append(table);host.append(region);
  const footer=el('div','');EamUiComponents.pagination(footer,{page:s.page,pages,total:raw.length,pageSize:8,onChange:page=>{s.page=page;rerender();}});host.append(footer);EamUiComponents.decorateTables();if(!raw.length)EamUiComponents.setTableStatus(table,'empty');
 }
 return {render,state};
})();
